from pathlib import Path
import re

p = Path('index.html')
s = p.read_text(encoding='utf-8')

if 'data-text-library-v2' in s:
    print('text library v2 already present')
    raise SystemExit(0)

css = r'''
/* data-text-library-v2 */
.textHead{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.textHead h2{margin:0 0 5px;font-size:25px}.textStats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.textStat{border:1px solid var(--line);background:#fffdfa;border-radius:17px;padding:13px}.textStat b{display:block;font-size:24px}.textStat span{font-size:12px;color:var(--muted)}.textForm{margin-top:14px}.textFormGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.textForm textarea{min-height:220px;margin-top:10px}.textTools{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:10px}.textListTop{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:10px}.textFilters{display:flex;gap:8px;flex-wrap:wrap}.textFilters input,.textFilters select{min-width:0}.textList{display:grid;gap:10px}.textItem{border:1px solid rgba(95,85,70,.12);background:#fffdfa;border-radius:18px;padding:16px}.textItemTop{display:flex;justify-content:space-between;gap:12px}.textItem h3{margin:0 0 5px;font-size:19px}.textItemMeta{font-size:12px;color:var(--muted)}.textSnippet{margin-top:9px;color:#5d5f57;line-height:1.55;font-size:14px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.textItemActions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.textItemActions button{padding:8px 11px}.dangerSoft{border:1px solid #e4c8c3;background:#fbefed;color:var(--r);border-radius:13px}.focusText .top,.focusText .nav{display:none!important}.focusText .wrap{max-width:none;padding:0!important}.focusText #text{display:block;min-height:100dvh}.textReader{min-height:100dvh;border:0!important;border-radius:0!important;box-shadow:none!important;background:var(--bg)!important;padding:108px 18px 100px!important;position:relative}.readerTop{position:absolute;top:0;left:0;right:0;height:88px;padding:max(16px,env(safe-area-inset-top)) 18px 0;display:flex;justify-content:center;align-items:center}.readerBack{position:absolute;left:13px;top:max(14px,env(safe-area-inset-top));width:48px;height:48px;border:0;background:transparent;border-radius:50%;font-size:40px;line-height:40px;padding:0}.readerTitle{max-width:62%;text-align:center}.readerTitle b{display:block;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.readerTitle span{font-size:11px;color:var(--muted)}.readerEdit{position:absolute;right:16px;top:max(21px,calc(env(safe-area-inset-top) + 7px));border:0;background:transparent;color:var(--muted)}.readerPanel{max-width:760px;width:100%;margin:auto}.readerActions{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.readerActions button{padding:11px 7px}.sentenceBox{margin-top:18px;min-height:250px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:26px 8px}.sentenceIndex{font-size:12px;color:var(--muted);margin-bottom:16px}.sentenceText{font-size:24px;line-height:1.7;max-width:680px}.sentenceText.hiddenText{filter:blur(10px);user-select:none}.sentenceNav{display:grid;grid-template-columns:1fr 1.4fr 1fr;gap:9px;width:100%;margin-top:18px}.sentenceNav button{padding:13px 8px}.readerFull{margin-top:14px}.fullText{white-space:pre-wrap;line-height:1.8;font-size:16px;max-height:300px;overflow:auto;padding:14px;border:1px solid var(--line);border-radius:15px;background:#fffdfa}.fullText.hiddenText{filter:blur(9px);user-select:none}.addFromText{margin-top:14px}.addGrid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:10px}.addGrid input{width:100%}.collectionBadge{display:inline-block;border:1px solid var(--line);background:#fffdfa;border-radius:999px;padding:4px 8px;font-size:11px;color:var(--muted)}
@media(max-width:560px){.textFormGrid,.addGrid{grid-template-columns:1fr}.textStats{grid-template-columns:repeat(3,1fr)}.readerActions{grid-template-columns:1fr 1fr 1fr}.sentenceText{font-size:22px}.textListTop{align-items:stretch;flex-direction:column}.textFilters{display:grid;grid-template-columns:1fr 1fr}.textFilters input{grid-column:1/3}}
'''
s = s.replace('</style>', css + '</style>', 1)

s = s.replace("document.body.classList.remove('focusStudy','focusType');", "document.body.classList.remove('focusStudy','focusType','focusText');", 1)
s = s.replace("['text','文本','文本听力']", "['text','文本','文本库']", 1)

# add reader state next to existing globals, without touching persisted state format
s = s.replace("cur='home',sess=null,ts=null", "cur='home',sess=null,ts=null,tx=null,textEditId=null", 1)

new_block = r'''function ensureTexts(){if(!Array.isArray(S.texts))S.texts=[]}
function textCollections(){ensureTexts();var a=[];S.texts.forEach(function(t){var c=(t.collection||'未分类').trim()||'未分类';if(a.indexOf(c)<0)a.push(c)});return a.sort()}
function textSentences(body){var m=String(body||'').replace(/\r/g,'').match(/[^.!?。！？\n]+[.!?。！？]+|[^.!?。！？\n]+(?=\n|$)/g)||[];return m.map(function(x){return x.trim()}).filter(Boolean)}
function textWordCount(body){var m=String(body||'').match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g);return m?m.length:0}
function textFmtTime(ts){if(!ts)return'从未打开';var d=new Date(ts),now=new Date(),same=d.toDateString()===now.toDateString();return same?'今天 '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'):(d.getMonth()+1)+'/'+d.getDate()}
function textSaveItem(editId){ensureTexts();var title=$('txtTitle').value.trim(),collection=$('txtCollection').value.trim()||'未分类',body=$('txtBody').value.trim();if(!title)return toast('先给这篇文本起个名字');if(!body)return toast('正文还是空的');var now=Date.now(),t=editId?S.texts.find(function(x){return x.id===editId}):null;if(t){t.title=title;t.collection=collection;t.body=body;t.updatedAt=now;t.sentence=Math.min(t.sentence||0,Math.max(0,textSentences(body).length-1))}else{S.texts.unshift({id:id(),title:title,collection:collection,body:body,createdAt:now,updatedAt:now,lastOpened:0,sentence:0,hidden:false,loop:false})}save();textEditId=null;toast(editId?'已更新文本':'已保存到文本库');textView()}
function textDelete(idv){ensureTexts();var t=S.texts.find(function(x){return x.id===idv});if(!t)return;if(!confirm('删除「'+t.title+'」？文本本身会删除，但已加入词库的单词不会受影响。'))return;S.texts=S.texts.filter(function(x){return x.id!==idv});save();textView()}
function textOpen(idv){ensureTexts();var t=S.texts.find(function(x){return x.id===idv});if(!t)return;t.lastOpened=Date.now();t.sentence=t.sentence||0;save();tx={id:t.id};document.body.classList.add('focusText');textReader()}
function textView(){ensureTexts();if(tx&&tx.id)return textReader();document.body.classList.remove('focusText');var cols=textCollections(),recent=S.texts.slice().sort(function(a,b){return(b.lastOpened||b.updatedAt||0)-(a.lastOpened||a.updatedAt||0)}),words=S.texts.reduce(function(n,t){return n+textWordCount(t.body)},0),editing=textEditId?S.texts.find(function(x){return x.id===textEditId}):null;$('text').innerHTML='<div class="card"><div class="textHead"><div><h2>文本库</h2><div class="small">把 transcript 和文章真正存下来，再从库里反复听，不用每次重新粘贴。</div></div><span class="collectionBadge">本机保存</span></div><div class="textStats"><div class="textStat"><b>'+S.texts.length+'</b><span>篇文本</span></div><div class="textStat"><b>'+cols.length+'</b><span>个文本库</span></div><div class="textStat"><b>'+words+'</b><span>英文词量</span></div></div></div><div class="card textForm"><div class="textHead"><div><h2 style="font-size:20px">'+(editing?'编辑文本':'新建文本')+'</h2><div class="small">例如：文本库「剑18」→ 文本「Test 3 Part 4」</div></div>'+(editing?'<button id="cancelTextEdit" class="soft">取消编辑</button>':'')+'</div><div class="textFormGrid" style="margin-top:12px"><div class="field"><label>文本标题</label><input id="txtTitle" placeholder="Test 3 Part 4" value="'+esc(editing?editing.title:'')+'"></div><div class="field"><label>所属文本库</label><input id="txtCollection" list="txtCollections" placeholder="剑18 / Part 4 / 自建素材" value="'+esc(editing?editing.collection:'')+'"><datalist id="txtCollections">'+cols.map(function(c){return'<option value="'+esc(c)+'">'}).join('')+'</datalist></div></div><textarea id="txtBody" placeholder="粘贴 transcript / 文章正文…">'+esc(editing?editing.body:'')+'</textarea><div class="textTools"><button id="saveText" class="primary">'+(editing?'保存修改':'保存到文本库')+'</button><label class="soft" style="cursor:pointer">导入 TXT<input id="txtFile" type="file" accept=".txt,text/plain" hidden></label></div></div><div class="card" style="margin-top:14px"><div class="textListTop"><div><b style="font-size:20px">我的文本</b><div class="small">点开后进入逐句听力模式</div></div><div class="textFilters"><input id="textSearch" placeholder="搜索标题/正文"><select id="textCollectionFilter"><option value="">全部文本库</option>'+cols.map(function(c){return'<option value="'+esc(c)+'">'+esc(c)+'</option>'}).join('')+'</select></div></div><div id="textList" class="textList"></div></div>';
$('saveText').onclick=function(){textSaveItem(editing&&editing.id)};if($('cancelTextEdit'))$('cancelTextEdit').onclick=function(){textEditId=null;textView()};$('txtFile').onchange=function(){var f=this.files[0];if(!f)return;var r=new FileReader();r.onload=function(){if(!$('txtTitle').value.trim())$('txtTitle').value=f.name.replace(/\.txt$/i,'');$('txtBody').value=String(r.result||'')};r.readAsText(f)};function drawTexts(){var q=$('textSearch').value.trim().toLowerCase(),c=$('textCollectionFilter').value,arr=recent.filter(function(t){return(!c||t.collection===c)&&(!q||(t.title+' '+t.collection+' '+t.body).toLowerCase().indexOf(q)>=0)});$('textList').innerHTML=arr.length?arr.map(function(t){var sent=textSentences(t.body).length;return'<div class="textItem"><div class="textItemTop"><div><h3>'+esc(t.title)+'</h3><div class="textItemMeta"><span class="collectionBadge">'+esc(t.collection||'未分类')+'</span> · '+sent+' 句 · '+textWordCount(t.body)+' 词 · '+textFmtTime(t.lastOpened)+'</div></div></div><div class="textSnippet">'+esc(t.body.replace(/\s+/g,' '))+'</div><div class="textItemActions"><button class="primary" data-open-text="'+t.id+'">继续听'+(t.sentence? ' · 第'+(t.sentence+1)+'句':'')+'</button><button class="soft" data-edit-text="'+t.id+'">编辑</button><button class="dangerSoft" data-del-text="'+t.id+'">删除</button></div></div>'}).join(''):'<div class="small" style="padding:22px 4px">还没有匹配的文本。</div>';document.querySelectorAll('[data-open-text]').forEach(function(b){b.onclick=function(){textOpen(this.dataset.openText)}});document.querySelectorAll('[data-edit-text]').forEach(function(b){b.onclick=function(){textEditId=this.dataset.editText;textView()}});document.querySelectorAll('[data-del-text]').forEach(function(b){b.onclick=function(){textDelete(this.dataset.delText)}})}$('textSearch').oninput=drawTexts;$('textCollectionFilter').onchange=drawTexts;drawTexts()}
function textCurrent(){ensureTexts();return tx&&S.texts.find(function(t){return t.id===tx.id})}
function textSpeakSentence(){var t=textCurrent();if(!t)return;var ss=textSentences(t.body),x=ss[t.sentence||0]||'';speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(x);u.lang='en-US';u.rate=S.set.rate||.92;u.onend=function(){var now=textCurrent();if(now&&now.loop&&tx&&tx.id===now.id)setTimeout(textSpeakSentence,180)};speechSynthesis.speak(u)}
function textMove(n){var t=textCurrent();if(!t)return;var ss=textSentences(t.body);t.sentence=Math.max(0,Math.min(ss.length-1,(t.sentence||0)+n));save();textReader();setTimeout(textSpeakSentence,50)}
function textReader(){var t=textCurrent();if(!t){tx=null;document.body.classList.remove('focusText');return textView()}document.body.classList.add('focusText');var ss=textSentences(t.body);if(!ss.length)ss=[t.body];t.sentence=Math.max(0,Math.min(ss.length-1,t.sentence||0));var curSent=ss[t.sentence]||'',source=t.collection||'文本词库';$('text').innerHTML='<div class="card textReader"><div class="readerTop"><button id="readerBack" class="readerBack">‹</button><div class="readerTitle"><b>'+esc(t.title)+'</b><span>'+esc(t.collection||'未分类')+'</span></div><button id="readerEdit" class="readerEdit">编辑</button></div><div class="readerPanel"><div class="readerActions"><button id="playFull" class="soft">全文朗读</button><button id="toggleText" class="soft">'+(t.hidden?'显示原文':'隐藏原文')+'</button><button id="toggleLoop" class="soft">单句循环 '+(t.loop?'开':'关')+'</button></div><div class="sentenceBox"><div class="sentenceIndex">第 '+(t.sentence+1)+' / '+ss.length+' 句</div><div class="sentenceText '+(t.hidden?'hiddenText':'')+'">'+esc(curSent)+'</div></div><div class="sentenceNav"><button id="prevSentence" class="soft" '+(t.sentence===0?'disabled':'')+'>上一句</button><button id="playSentence" class="primary">重听本句</button><button id="nextSentence" class="soft" '+(t.sentence===ss.length-1?'disabled':'')+'>下一句</button></div><div class="card readerFull"><div class="heatTitle"><div><b>全文</b><div class="small">长按可选中一个词，再填到下方加入词库</div></div></div><div id="fullText" class="fullText '+(t.hidden?'hiddenText':'')+'">'+esc(t.body)+'</div></div><div class="card addFromText"><div><b>从本文加入单词</b><div class="small">单词来源会自动记为「'+esc(source)+'」，例句默认取当前句。</div></div><div class="addGrid"><input id="textWord" placeholder="英文单词"><input id="textMeaning" placeholder="中文核心义，可留空"></div><div class="textTools"><button id="useSelection" class="soft">使用刚选中的词</button><button id="addTextWord" class="primary">加入词库</button></div></div></div></div>';
$('readerBack').onclick=function(){speechSynthesis.cancel();tx=null;document.body.classList.remove('focusText');textView()};$('readerEdit').onclick=function(){speechSynthesis.cancel();textEditId=t.id;tx=null;document.body.classList.remove('focusText');textView()};$('playFull').onclick=function(){speak(t.body)};$('playSentence').onclick=textSpeakSentence;$('prevSentence').onclick=function(){textMove(-1)};$('nextSentence').onclick=function(){textMove(1)};$('toggleText').onclick=function(){t.hidden=!t.hidden;save();textReader()};$('toggleLoop').onclick=function(){t.loop=!t.loop;save();textReader();if(t.loop)textSpeakSentence();else speechSynthesis.cancel()};$('useSelection').onclick=function(){var x=String(window.getSelection?window.getSelection().toString():'').trim().replace(/^[^A-Za-z'’-]+|[^A-Za-z'’-]+$/g,'');if(!x||/\s/.test(x)){toast('先在全文里只选中一个英文单词');return}$('textWord').value=x};$('addTextWord').onclick=function(){var x=$('textWord').value.trim(),zh=$('textMeaning').value.trim();if(!x||/\s/.test(x)){toast('请输入一个英文单词');return}add(x,zh,source,'','',curSent);save();toast('已加入 '+x+' · 来源 '+source);$('textWord').value='';$('textMeaning').value=''};save()}
function lib()'''

pattern = r'function textView\(\)\{.*?function lib\(\)'
s2, n = re.subn(pattern, new_block, s, count=1, flags=re.S)
if n != 1:
    raise SystemExit(f'could not replace text block: {n}')

p.write_text(s2, encoding='utf-8')
print('patched persistent text library')
